def backfill_receipt_times(apps,schema_editor):
    Submission=apps.get_model('core','Submission')
    ExecutionJob=apps.get_model('core','ExecutionJob')
    import uuid
    for offset in range(0,Submission.objects.count(),500):
        rows=list(Submission.objects.order_by('pk')[offset:offset+500])
        ids=[]
        for row in rows:
            value=row.response.get('job') if isinstance(row.response,dict) else None
            try:ids.append(uuid.UUID(str(value)))
            except ValueError:pass
        jobs={str(j.pk):j for j in ExecutionJob.objects.filter(pk__in=ids)}
        for row in rows:
            job=jobs.get(str(row.response.get('job'))) if isinstance(row.response,dict) else None
            if job and job.revision_id==row.revision_id:
                member=apps.get_model('core','Membership').objects.get(pk=row.membership_id)
                if member.user_id!=job.user_id:job=None
            else:job=None
            row.received_at=job.created_at if job else row.created_at
        Submission.objects.bulk_update(rows,['received_at'],batch_size=500)


